export function Citation({
  sourceLabel = "{{sourceLabel}}",
  index = {{index}},
  style = "{{style}}",
  accent = "{{accent}}",
}) {
  const markerStyle = {
    numeric: { borderRadius: 999, border: `1.5px solid ${accent}`, minWidth: "1.4em", height: "1.4em", padding: "0 0.3em", background: "transparent" },
    bracket: { borderRadius: 4, border: "none", minWidth: "1.4em", height: "1.4em", padding: "0 0.3em", background: `color-mix(in srgb, ${accent} 18%, #FAF7F2)` },
    superscript: { border: "none", minWidth: 0, height: "auto", padding: 0, verticalAlign: "super", fontSize: "0.68em", background: "transparent" },
  }[style] ?? {};
  const label = style === "bracket" ? `[${index}]` : index;
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 15, lineHeight: 1.7, color: "#241430",
      background: "#FAF7F2", maxWidth: 480, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      Large language models can produce inaccurate statements
      <details style={{ display: "inline" }}>
        <summary style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", margin: "0 0.15em",
          color: accent, font: "700 0.72em/1 system-ui, sans-serif", cursor: "pointer", listStyle: "none",
          verticalAlign: "baseline", ...markerStyle }}>{label}</summary>
        <span style={{ display: "block", marginTop: 6, padding: "8px 10px", borderRadius: 6, fontSize: "0.82em",
          color: "#241430", background: `color-mix(in srgb, ${accent} 14%, #FAF7F2)`, borderLeft: `3px solid ${accent}` }}>
          Source: {sourceLabel}
        </span>
      </details>
      , so claims should be checked against primary sources.
    </div>
  );
}
